(7644046, 1242119, 141319, '<td valign="top">I love this! Don''t know how well you will do in DPC with it, but you have at least 1 fan :-). Really cool picture.</td>', 'I love this! Don''t know how well you will do in DPC with it, but you have at least 1 fan :-). Really cool picture.', '2019-10-19 13:34:32.000000', NULL, 1),
(7644047, 1242153, 141319, '<td valign="top">I hope you let us into your secret how you made this. I really like the effect you achieved here.</td>', 'I hope you let us into your secret how you made this. I really like the effect you achieved here.', '2019-10-19 13:35:46.000000', NULL, 1),
(7644048, 1241953, 141319, '<td valign="top">Nice. I know that doesn''t mean much really,  but that was the first thought I had when I saw it :-).</td>', 'Nice. I know that doesn''t mean much really,  but that was the first thought I had when I saw it :-).', '2019-10-19 13:37:38.000000', NULL, 1),
(7644119, 1242183, 65234, '<td valign="top">This one''s interesting. On the one hand, it''s a fantastic image. It looks like some sort of other-worldly bishops to me, on the altar during a ceremony. On the other hand, I''m having trouble figuring out what''s photographic about it. Really torn on giving it a high score because of that, but ... it''s a fabulous image. I''d love to see the original and learn how you transformed it.</td>', 'This one''s interesting. On the one hand, it''s a fantastic image. It looks like some sort of other-worldly bishops to me, on the altar during a ceremony. On the other hand, I''m having trouble figuring out what''s photographic about it. Really torn on giving it a high score because of that, but ... it''s a fabulous image. I''d love to see the original and learn how you transformed it.', '2019-10-21 09:58:26.000000', NULL, 1),
(7644120, 1242170, 65234, '<td valign="top">It''s a little jumping spider! They have the cutest eyes. Kind of like this guy being sideways. Like finding him on a wall.</td>', 'It''s a little jumping spider! They have the cutest eyes. Kind of like this guy being sideways. Like finding him on a wall.', '2019-10-21 09:59:23.000000', NULL, 1),
